BEGIN READ ONLY;
SET LOCAL statement_timeout='8s';
SELECT clock_timestamp() observed_at,
 (SELECT jsonb_build_object('owner_id',owner_id,'owner_fence',owner_fence,'stopped',stopped,'provider_requests',provider_requests,'max_provider_requests',max_provider_requests,'stored_bytes',stored_bytes,'max_source_bytes',max_source_bytes) FROM population_top3000_202608_202609_v1.acquisition_control WHERE singleton) controls,
 (SELECT jsonb_agg(jsonb_build_object('task_id',task_id,'stage',stage,'status',status,'checkpoint',checkpoint,'blocker_code',blocker_code,'payload',payload) ORDER BY stage) FROM population_top3000_202608_202609_v1.pipeline_task WHERE family_id='N01') tasks,
 (SELECT jsonb_agg(jsonb_build_object('source_id',p.source_id,'page',p.page_number,'records',p.result_count,'wire_bytes',p.wire_bytes,'stored_bytes',d.content_bytes,'terminal',p.next_url IS NULL,'stored_hash_valid',d.source_sha256=encode(sha256(convert_to(d.content_text,'UTF8')),'hex'),'stored_byte_count_valid',d.content_bytes=octet_length(d.content_text),'envelope_keys',(SELECT jsonb_agg(k ORDER BY k) FROM jsonb_object_keys(d.content_text::jsonb) k),'provider_status',d.content_text::jsonb->'status','provider_count',d.content_text::jsonb->'count','normalized',p.normalized_at IS NOT NULL) ORDER BY p.page_number) FROM population_top3000_202608_202609_v1.massive_news_archive_page_v1 p JOIN population_top3000_202608_202609_v1.source_document d USING(source_id)) pages,
 (SELECT jsonb_build_object('source_records',count(*),'valid_in_window_publication_times',count(*) FILTER(WHERE population_top3000_202608_202609_v1.massive_news_timestamp_v1(v->>'published_utc')>=timestamptz '2026-08-01 04:00+00' AND population_top3000_202608_202609_v1.massive_news_timestamp_v1(v->>'published_utc')<timestamptz '2026-10-01 04:00+00'),'first_provider_timestamp',min(v->>'published_utc'),'last_provider_timestamp',max(v->>'published_utc'),'missing_ids',count(*) FILTER(WHERE coalesce(v->>'id','')=''),'record_field_keys',(SELECT jsonb_agg(DISTINCT key ORDER BY key) FROM population_top3000_202608_202609_v1.massive_news_archive_page_v1 pp JOIN population_top3000_202608_202609_v1.source_document dd USING(source_id) CROSS JOIN LATERAL jsonb_array_elements(dd.content_text::jsonb->'results') vv CROSS JOIN LATERAL jsonb_object_keys(vv) key WHERE pp.page_number=1)) FROM population_top3000_202608_202609_v1.massive_news_archive_page_v1 p JOIN population_top3000_202608_202609_v1.source_document d USING(source_id) CROSS JOIN LATERAL jsonb_array_elements(d.content_text::jsonb->'results') v WHERE p.page_number=1) first_page_review;
ROLLBACK;
